fn bubble_sort(mut arr: [int]) -> [int] {
    let n = arr.len()
    for i in 0..n {
        for j in 0..(n-i-1) {
            if arr[j] > arr[j+1] {
                let tmp = arr[j]
                arr[j] = arr[j+1]
                arr[j+1] = tmp
            }
        }
    }
    return arr
}

