use quantumai::*;

fn main() {
    // 1. Load and analyse data
    let ds = DataPipeline::load("iris").normalize().dataset();
    DataQualityReport::analyze(&ds.x, &ds.y, &["f1","f2","f3","f4"], &["a","b","c"]).print_simple();

    // 2. Split
    let (train, test) = ds.train_test_split(0.2);

    // 3. Hyperparameter search
    let best = tune(&train, 8);

    // 4. Train
    let mut model = Model::create("classifier");
    model.lr = best.best_lr;
    model.train(&train.x, &train.y, 150, true);

    // 5. Benchmark
    let report = BenchmarkReport::run(&mut model, &train.x, &train.y, &test.x, &test.y, 3, &["a","b","c"]);
    report.print(&["a","b","c"]);
    AIAssistant::analyze(&report);
    ModelCard::from_benchmark(&model, &report).print();
    model.save("model.json");
}

